"""UMUD v25 AdaBN launcher (generated by kaggle/adabn_v25/build_kernel.py: edit the builder, not this file).

PREREG artifacts/candidates_v25/PREREG_v25_adabn.json (sha256 in the tables). BatchNorm running statistics ONLY, re-estimated
per domain from unlabeled images (user approval 2026-11-05). Stages of adabn_stages.py run as subprocesses:
  2 GPUs: cuda:0 apo -> ours, cuda:1 orient     1 GPU: apo, orient, ours in turn     cpusmoke: CPU, in turn
then finalize (CPU). Outputs /kaggle/working/v25 (artifacts/candidates_v25/README.md). GPL-3.0-only.
"""
import base64, json, os, subprocess, sys, threading, time, zlib
from pathlib import Path

MODE = "cpusmoke"
SOURCE_SHA256 = {'apo_fix_src.py': '3fcf79708d6e0b623e8e037fd45266f5c65dde77f14a52e672d55244286739c4', 'fo_src.py': 'e396d078794957eeb1a72c66469d13bf379688e6d918d83f8ba383886532abac', 'pipeline.py': 'e33606355968b1c97b03ae1a2dca4c882b5d874a02409f099670e1ca1763d213', 'adabn_stages.py': '80c72b7398173ef84e6f652c8d63f113b3085aa0e5ca499072af46fceeebdca3'}
SOURCES = {
"apo_fix_src.py": "",
"fo_src.py": "",
"pipeline.py": "",
"adabn_stages.py": ""
}
TABLES_Z = ""
TMP = Path("/tmp/v25")
OUT = Path("/kaggle/working/v25")
T0 = time.time()
DEADLINE_S = 10.5 * 3600


def say(msg):
    print(f"[launcher {time.time() - T0:8.1f}s] {msg}", flush=True)


def pump(p, stage, lf):
    for line in p.stdout:
        print(f"[{stage}] {line}", end="", flush=True)
        lf.write(line)
        lf.flush()


def start(stage, gpu, codes=None):
    env = dict(os.environ, V25_MODE=MODE, V25_LAUNCH_T0=str(T0), V25_DEADLINE_S=str(DEADLINE_S), PYTHONUNBUFFERED="1")
    env["CUDA_VISIBLE_DEVICES"] = "" if gpu is None else str(gpu)
    if codes is not None:
        env["V25_CODES"] = json.dumps(codes)
    (OUT / "logs").mkdir(parents=True, exist_ok=True)
    lf = open(OUT / "logs" / f"{stage}.log", "w", encoding="utf-8")
    p = subprocess.Popen([sys.executable, "-u", str(TMP / "adabn_stages.py"), "--stage", stage], cwd=str(TMP),
                         stdout=subprocess.PIPE, stderr=subprocess.STDOUT, text=True, env=env)
    th = threading.Thread(target=pump, args=(p, stage, lf), daemon=True)
    th.start()
    say(f"started {stage} on {'cpu' if gpu is None else 'cuda:' + str(gpu)} (pid {p.pid})")
    return stage, p, th, lf, time.time()


def finish(h):
    stage, p, th, lf, t = h
    code = p.wait()
    th.join()
    lf.close()
    say(f"stage {stage} exit={code} ({(time.time() - t) / 60:.1f} min)")
    return code


def n_gpus():
    try:
        return subprocess.run(["nvidia-smi", "-L"], capture_output=True, text=True, timeout=60).stdout.count("GPU ")
    except Exception:  # noqa: BLE001
        return 0


def ensure_smp():
    probe = [sys.executable, "-c", "import segmentation_models_pytorch as s; print(s.__version__)"]
    r = subprocess.run(probe, capture_output=True, text=True)
    ver = r.stdout.strip().splitlines()[-1] if r.returncode == 0 and r.stdout.strip() else None
    if ver != "0.5.0":
        say(f"pip install segmentation-models-pytorch==0.5.0 (found {ver})")
        subprocess.run([sys.executable, "-m", "pip", "install", "--quiet", "segmentation-models-pytorch==0.5.0"])
        r = subprocess.run(probe, capture_output=True, text=True)
        ver = r.stdout.strip().splitlines()[-1] if r.returncode == 0 and r.stdout.strip() else r.stderr[-300:]
    return ver


def main():
    TMP.mkdir(parents=True, exist_ok=True)
    OUT.mkdir(parents=True, exist_ok=True)
    for name, blob in SOURCES.items():
        (TMP / name).write_text(zlib.decompress(base64.b64decode(blob)).decode("utf-8"), encoding="utf-8")
    (TMP / "tables.json").write_text(zlib.decompress(base64.b64decode(TABLES_Z)).decode("utf-8"), encoding="utf-8")
    smp_ver = ensure_smp()  # once, before any stage: parallel stages must not pip-install concurrently
    g = 0 if MODE == "cpusmoke" else n_gpus()
    say(f"mode={MODE} python={sys.version.split()[0]} cpus={os.cpu_count()} gpus={g} smp={smp_ver}")
    codes = {}
    if MODE == "full" and g == 0:
        codes["error"] = "no GPU attached: the full run needs the T4 accelerator (use cpusmoke for a CPU dry run)"
        say(codes["error"])
    elif g >= 2:
        a = start("apo", 0)
        o = start("orient", 1)
        codes["apo"] = finish(a)
        codes["ours"] = finish(start("ours", 0))
        codes["orient"] = finish(o)
    else:
        for st in ("apo", "orient", "ours"):
            codes[st] = finish(start(st, 0 if g else None))
    codes["finalize"] = finish(start("finalize", None, codes))
    (OUT / "exit_codes.json").write_text(json.dumps({"exit_codes": codes, "mode": MODE, "smp": smp_ver, "gpus": g,
                                                     "source_sha256": SOURCE_SHA256,
                                                     "minutes": (time.time() - T0) / 60}, indent=1))
    say(f"exit codes {codes}; {(time.time() - T0) / 60:.1f} min")
    total = 0
    for p in sorted(OUT.rglob("*")):
        if p.is_file():
            total += p.stat().st_size
    say(f"outputs {total / 1e6:.1f} MB under {OUT}")


main()
